Route::get('/',fn()=>redirect()->route('login'));Route::middleware('guest')->group(function(){Route::get('/login',[AuthController::class,'showLogin'])->name('login');Route::post('/login',[AuthController::class,'login'])->name('login.post');Route::get('/register',[AuthController::class,'showRegister'])->name('register');Route::post('/register',[AuthController::class,'register'])->name('register.post');});Route::middleware('auth')->group(function(){Route::post('/logout',[AuthController::class,'logout'])->name('logout');Route::get('/dashboard',[AuthController::class,'dashboard'])->name('dashboard');Route::prefix('admin')->name('admin.')->middleware('role:admin')->group(function(){Route::get('/dashboard',[AdminController::class,'dashboard'])->name('dashboard');Route::get('/children',[AdminController::class,'children'])->name('children');Route::get('/vaccines',[AdminController::class,'vaccines'])->name('vaccines');Route::get('/vaccines/{vaccine}/edit',[AdminController::class,'editVaccine'])->name('vaccines.edit');Route::post('/vaccines',[AdminController::class,'storeVaccine'])->name('vaccines.store');Route::put('/vaccines/{vaccine}',[AdminController::class,'updateVaccine'])->name('vaccines.update');Route::delete('/vaccines/{vaccine}',[AdminController::class,'deleteVaccine'])->name('vaccines.delete');Route::get('/hospitals',[AdminController::class,'hospitals'])->name('hospitals');Route::get('/hospitals/{hospital}/edit',[AdminController::class,'editHospital'])->name('hospitals.edit');Route::put('/hospitals/{hospital}',[AdminController::class,'updateHospital'])->name('hospitals.update');Route::post('/hospitals',[AdminController::class,'storeHospital'])->name('hospitals.store');Route::delete('/hospitals/{hospital}',[AdminController::class,'deleteHospital'])->name('hospitals.delete');Route::get('/bookings',[AdminController::class,'bookings'])->name('bookings');Route::put('/bookings/{appointment}',[AdminController::class,'updateBooking'])->name('bookings.update');Route::get('/reports',[AdminController::class,'reports'])->name('reports');});Route::prefix('parent')->name('parent.')->middleware('role:parent')->group(function(){Route::get('/dashboard',[ParentController::class,'dashboard'])->name('dashboard');Route::get('/children',[ParentController::class,'children'])->name('children');Route::post('/children',[ParentController::class,'storeChild'])->name('children.store');Route::put('/children/{child}',[ParentController::class,'updateChild'])->name('children.update');Route::delete('/children/{child}',[ParentController::class,'destroyChild'])->name('children.delete');Route::get('/hospitals',[ParentController::class,'hospitals'])->name('hospitals');Route::post('/book',[ParentController::class,'book'])->name('book');Route::get('/appointments',[ParentController::class,'appointments'])->name('appointments');Route::get('/records',[ParentController::class,'records'])->name('records');Route::get('/profile',[ParentController::class,'profile'])->name('profile');Route::put('/profile',[ParentController::class,'updateProfile'])->name('profile.update');});Route::prefix('hospital')->name('hospital.')->middleware('role:hospital')->group(function(){Route::get('/dashboard',[HospitalController::class,'dashboard'])->name('dashboard');Route::get('/profile',[HospitalController::class,'profile'])->name('profile');Route::put('/profile',[HospitalController::class,'updateProfile'])->name('profile.update');Route::get('/appointments',[HospitalController::class,'appointments'])->name('appointments');Route::put('/appointments/{appointment}/complete',[HospitalController::class,'complete'])->name('appointments.complete');});});
